from __future__ import annotations

def is_product_sum(number, factors):
    return number == sum(factors) and number == eval('*'.join(map(str, factors)))

def find_minimal_product_sum(k):

    def is_product_sum(number, factors):
        product = 1
        summation = 0
        for factor in factors:
            product *= factor
            summation += factor
        return product == number and summation == number
    min_product_sums = [float('inf')] * (k + 1)
    min_product_sums[2] = 4
    for i in range(3, k + 1):
        for j in range(2, i + 1):
            if is_product_sum(i, [j] * i):
                min_product_sums[i] = i
                break
            for factors in range(2, i):
                if is_product_sum(i, [factors] * (i - factors) + [i - factors]):
                    min_product_sums[i] = i
                    break
                if factors * (i - factors) > i:
                    break
    return sum(min_product_sums[2:k + 1])

def generate_factors(k, start=1):
    factors = []
    for i in range(start, k + 1):
        if k % i == 0:
            factors.append(i)
    return factors

def productsum(n):
    minimal_product_sums = set()
    for k in range(2, n + 1):
        minimal_product_sum = find_minimal_product_sum(k)
        minimal_product_sums.add(minimal_product_sum)
    return sum(minimal_product_sums)

