    return str(n ** 2).endswith(str(n))

def count_green_numbers(limit):
    count = 0
    n = 1
    while count < limit:
        if is_green(n):
            count += 1
        n += 1
    return n - 1

def find_green_number(n):
    count = 0
    i = 1
    while True:
        if is_green(i):
            count += 1
            if count == n:
                return i
        i += 1

def green(n):
    return find_green_number(n)

