from __future__ import annotations

def parse_poly(poly):
    import re
    from collections import defaultdict
    pattern = '([+-]?\\d*)([a-z]+)'
    matches = re.findall(pattern, poly)
    monomials = defaultdict(int)
    for coeff, monomial in matches:
        if coeff == '':
            coeff = '1'
        elif coeff == '-':
            coeff = '-1'
        monomials[monomial] += int(coeff)
    sorted_monomials = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))
    return sorted_monomials

def sort_monomials(monomials):
    return sorted(monomials, key=lambda x: (len(x), x))

def combine_like_terms(monomials):
    combined = {}
    for coeff, monomial in monomials:
        key = tuple(sorted(monomial))
        if key in combined:
            combined[key] += coeff
        else:
            combined[key] = coeff
    return [(coeff, ''.join(sorted(key))) for key, coeff in combined.items()]

def simplify(poly):
