    pattern = '([+-]?\\d*)([a-z]+)'
    matches = re.findall(pattern, poly)
    return [(int(coeff), monomial) for coeff, monomial in matches]

def sort_monomials(monomials):
    return sorted(monomials, key=lambda x: (len(x), x))

def combine_like_terms(monomials):
    combined = {}
    for coeff, monomial in monomials:
        if monomial in combined:
            combined[monomial] += coeff
        else:
            combined[monomial] = coeff
    return [(coeff, monomial) for monomial, coeff in combined.items()]

def simplify(poly):
    monomials = parse_poly(poly)
    sorted_monomials = sort_monomials(monomials)
    combined_monomials = combine_like_terms(sorted_monomials)
    return ''.join(combined_monomials)

