def parse_poly(poly):
    import re
    from collections import defaultdict
    terms = re.split('([+-])', poly)
    terms = [t.strip() for t in terms if t.strip()]
    coefficients = defaultdict(int)
    for term in terms:
        if term:
            sign = 1 if term[0] != '-' else -1
            if term[0] in '+-':
                term = term[1:]
            if 'x' not in term:
                coefficients[''] += sign * int(term)
            else:
                monomial = re.sub('(\\d+)', '\\1x', term)
                coefficients[monomial] += sign * int(re.search('(\\d+)', term).group(1))
    sorted_monomials = sorted(coefficients.keys(), key=lambda x: (len(x), x))
    simplified_poly = []
    for monomial in sorted_monomials:
        coeff = coefficients[monomial]
        if coeff != 0:
            if monomial:
                simplified_poly.append(f'{coeff}{monomial}')
            else:
                simplified_poly.append(str(coeff))
    result = ''.join(simplified_poly)
    if result.startswith('+'):
        result = result[1:]
    return result

def sort_monomials(monomials):
    return sorted(monomials, key=lambda x: (len(x), x))

def combine_like_terms(monomials):
    combined = {}
    for coeff, monomial in monomials:
        key = tuple(sorted(monomial))
        if key in combined:
            combined[key] += coeff
        else:
            combined[key] = coeff
    return [(coeff, ''.join(sorted(monomial))) for monomial, coeff in combined.items()]

