    terms = re.findall('[-+]?\\d*\\.?\\d+[a-zA-Z]+', poly)
    result = []
    for term in terms:
        coeff, monomial = (term[0], term[1:])
        result.append((int(coeff), monomial))
    return result

def sort_monomials(monomials):
    return sorted(monomials, key=lambda x: (len(x[1].split('*')), x[1]))

def combine_like_terms(monomials):
    combined = {}
    for coeff, monomial in monomials:
        if monomial in combined:
            combined[monomial] += coeff
        else:
            combined[monomial] = coeff
    return [(coeff, monomial) for monomial, coeff in combined.items()]

def simplify(poly):
    monomials = parse_poly(poly)
    combined_monomials = combine_like_terms(monomials)
    sorted_monomials = sort_monomials(combined_monomials)
    return ''.join(sorted_monomials)

