from __future__ import annotations

def parse_poly(poly):
    import re
    terms = re.findall('[-+]?\\d*\\.?\\d+[a-zA-Z]+', poly)
    result = []
    for term in terms:
        if term[0] == '+':
            term = term[1:]
        coefficient = float(term.split('x')[0]) if 'x' in term else float(term)
        monomial = term.replace(str(coefficient), '').replace('+', '').replace('-', '')
        result.append((coefficient, monomial))
    return result

