        key = tuple(sorted(monomial))
        if key in combined:
            combined[key] += coeff
        else:
            combined[key] = coeff
    return [(coeff, ''.join(sorted(monomial))) for monomial, coeff in combined.items()]

def simplify(poly):
    monomials = parse_poly(poly)
    combined_monomials = combine_like_terms(monomials)
    sorted_monomials = sort_monomials(combined_monomials)
